#![cfg(windows)]

/// C bindings of this crate's headers (generated by build.rs), re-exported with those it builds on.
/// Every user is behind a fixture feature, hence unused_imports.
#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    unused_imports,
    clippy::all
)]
mod sys {
    pub use rsf_orchestrator::sys::*;
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}

#[cfg(feature = "streamline-dispatch")]
mod streamline_dispatch;
#[cfg(feature = "streamline-selected")]
mod streamline_selected;
#[cfg(feature = "wsi-dispatch")]
mod wsi;
#[cfg(feature = "wsi-dispatch")]
mod wsi_abi;

#[cfg(any(
    feature = "xess-device",
    feature = "xess-sr",
    feature = "xess-input-range"
))]
#[cfg(feature = "xess-device")]
mod xess_interop;

#[cfg(feature = "xess-device")]
mod xess_present;

#[cfg(feature = "xess-input-range")]
mod xess_input_range;
